pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 tsSeed) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0); // ensure payout transfer succeeds
        vm.deal(actor, 10 ether);

        // find a timestamp that makes the pseudo-random draw a WIN for this actor
        bool won = false;
        uint256 ts;
        for (uint256 k = 0; k < 256 && !won; k++) {
            ts = tsSeed + k;
            uint256 r = uint(keccak256(abi.encodePacked(ts, block.difficulty, actor))) % 2;
            if (r == 0) won = true;
        }
        vm.assume(won);

        vm.warp(ts);
        vm.prank(actor);
        c.play{value: 10}();

        // GENERAL RULE: after a winning round the whole pot is paid out and the pot is empty.
        assertTrue(c.pot() == 0);
    }
}

