pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // deploy from a plain EOA so the bank payee accepts the 1-wei fee transfer
        vm.prank(address(1));
        c = new C();
    }

    function testFuzz_property(uint256 t1, uint256 t2, address actor) public {
        vm.assume(actor != address(0) && actor != address(1) && actor.code.length == 0);
        vm.deal(actor, 20);

        uint256 expectedPot = 0;

        // round 1
        vm.warp(t1);
        vm.roll(1);
        vm.prank(actor);
        bool ok1;
        try c.play{value: 10}() { ok1 = true; } catch { ok1 = false; }
        if (ok1) {
            uint256 rnd = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;
            if (rnd == 0) { expectedPot = 0; } else { expectedPot += 10; }
        }

        // round 2
        vm.warp(t2);
        vm.roll(1);
        vm.prank(actor);
        bool ok2;
        try c.play{value: 10}() { ok2 = true; } catch { ok2 = false; }
        if (ok2) {
            uint256 rnd = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;
            if (rnd == 0) { expectedPot = 0; } else { expectedPot += 10; }
        }

        assertTrue(c.pot() == expectedPot);
    }
}

