pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address winner1, address winner2, uint256 t1, uint256 t2) public {
        // widen domain, only exclude degenerate addresses
        if (winner1 == address(0)) winner1 = address(0xBEEF);
        if (winner2 == address(0)) winner2 = address(0xCAFE);
        vm.assume(winner1 != winner2);
        t1 = bound(t1, 1, type(uint64).max);
        t2 = bound(t2, 1, type(uint64).max);
        vm.roll(1); // fix difficulty so the fuzzer controls the win condition via (t, actor)

        // only admissible scenarios: both designated players win their round
        vm.assume(uint(keccak256(abi.encodePacked(t1, block.difficulty, winner1))) % 2 == 0);
        vm.assume(uint(keccak256(abi.encodePacked(t2, block.difficulty, winner2))) % 2 == 0);

        vm.deal(winner1, 10);
        vm.deal(winner2, 10);

        // round 1: winner1 wins the fresh pot of 10 -> pot resets to 0
        vm.warp(t1);
        vm.prank(winner1);
        c.play{value: 10}();

        // round 2: winner2 wins immediately after -> must be paid exactly the fresh pot (10) minus fee (1)
        vm.warp(t2);
        vm.prank(winner2);
        c.play{value: 10}();

        // the second consecutive winner must receive exactly TICKET_AMOUNT - FEE_AMOUNT
        assertTrue(winner2.balance == 10 + (10 - 1));
    }
}

