pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 seed) public {
        // Admissible domain: a plain recipient that can receive Ether via transfer.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c)); // C has no payable fallback; exclude it as player
        vm.assume(actor.code.length == 0); // plain EOA recipient for transfers

        // Fix difficulty, then find the first timestamp >= seed where the player wins.
        vm.roll(1);
        uint256 diff = block.difficulty;
        uint256 ts = seed;
        for (uint256 i = 0; i < 256; i++) {
            ts = seed + i;
            if (uint256(keccak256(abi.encodePacked(ts, diff, actor))) % 2 == 0) break;
        }
        vm.warp(ts);

        // Play one ticket: this input is a winning play for both P and M.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.play{value: 10}();

        // General rule: a winning play empties the pot (bank takes fee, player drains rest, pot reset to 0).
        assertTrue(c.pot() == 0);
    }
}

