pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, uint256 warp, uint256 roll) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        uint256 ticket = c.TICKET_AMOUNT();
        vm.deal(actor, type(uint256).max);
        vm.warp(warp);
        vm.roll(roll);
        vm.prank(actor);
        bool ok;
        try c.play{value: amount}() { ok = true; } catch { ok = false; }
        assertTrue(!ok || c.pot() == 0 || c.pot() == ticket);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint amount) public {
        require(amount == 10);
        require(address(this).balance >= 2 * amount);

        uint p0 = c.pot();
        c.play{value: amount}();
        uint p1 = c.pot();

        c.play{value: amount}();
        uint p2 = c.pot();

        assert(p1 == 0 || p1 == p0 + amount);
        assert(p2 == 0 || p2 == p1 + amount);
    }
}

